#include <stdexcept>
struct E : std::runtime_error { E():std::runtime_error("E"){} };
int main() {
  try { throw E(); }
  catch (const std::runtime_error& e) { std::cout << e.what() << ' '; }
  catch (const E& e) { std::cout << "E " << e.what() << ' '; }
  std::cout << "end\n";
}
