class Buf {
  int* p_ = nullptr; size_t n_ = 0;
public:
  ~Buf() { delete[] p_; }
  Buf(Buf&& o) noexcept : p_(o.p_), n_(o.n_) { o.p_ = nullptr; o.n_ = 0; }   // 窃取并置空源
  Buf& operator=(Buf&& o) noexcept {
    if (this != &o) { delete[] p_; p_ = o.p_; n_ = o.n_; o.p_ = nullptr; o.n_ = 0; }
    return *this;
  }
};

void push_back(const T& v) {
  if (size_ == cap_) {
    size_t nc = cap_ ? cap_ * 2 : 1;
    auto np = std::make_unique<T[]>(nc);          // 先建新缓冲（可能抛，但只影响 np）
    for (size_t i = 0; i < size_; ++i) np[i] = data_[i];  // 拷贝旧数据
    np[size_] = v;                                // 放入新元素
    data_ = std::move(np);                        // 提交：unique_ptr 移动 noexcept
    cap_ = nc;                                    // 原生赋值不抛
  } else {
    data_[size_] = v;
  }
  ++size_;
}

